    TaskSpec('TSK-101', 'ledger_reconciliation', {'ledger_id': 'GL-8820', 'amount': 450000.0}),
    TaskSpec('TSK-102', 'fraud_detection', {'account_id': 'ACC-912', 'velocity_score': 0.94}),
    TaskSpec('TSK-103', 'variance_analysis', {'quarter': 'Q3', 'discrepancy_usd': 12500.0})
]

telemetry = supervisor.dispatch_batch(tasks_to_process)
print(json.dumps(telemetry, indent=2))

