import json
import time
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Any, Callable

@dataclass
class ToolDefinition:
    name: str
    description: str
    parameters_schema: Dict[str, str]
    handler: Callable[[Dict[str, Any]], Dict[str, Any]] = field(repr=False)

class EnterpriseToolRegistry:
    def __init__(self):
        self.tools: Dict[str, ToolDefinition] = {}
        self.execution_log: List[Dict[str, Any]] = []

    def register_tool(self, name: str, description: str, parameters_schema: Dict[str, str], handler: Callable) -> None:
        self.tools[name] = ToolDefinition(name, description, parameters_schema, handler)

    def semantic_match_tools(self, query: str) -> List[Dict[str, Any]]:
        # Simulated semantic keyword matching against tool descriptors
        matched = []
        q_lower = query.lower()
        for t_name, tool in self.tools.items():
            if any(term in tool.description.lower() for term in q_lower.split()):
                matched.append({'tool_name': t_name, 'parameters': tool.parameters_schema})
        return matched

    def dispatch_tool_call(self, tool_name: str, arguments: Dict[str, Any]) -> Dict[str, Any]:
        if tool_name not in self.tools:
            return {'status': 'ERROR_TOOL_NOT_FOUND', 'tool_name': tool_name}

        tool = self.tools[tool_name]
        start_time = time.time()
        try:
            result = tool.handler(arguments)
            duration_ms = round((time.time() - start_time) * 1000.0, 2)
            record = {
                'status': 'SUCCESS',
                'tool_name': tool_name,
                'duration_ms': duration_ms,
                'result': result
            }
            self.execution_log.append(record)
            return record
        except Exception as e:
            return {'status': 'ERROR_EXECUTION_FAILURE', 'error': str(e)}

# Execution: Register enterprise banking tools and dispatch a foreign exchange query
registry = EnterpriseToolRegistry()

def get_fx_rate_handler(args: Dict[str, Any]) -> Dict[str, Any]:
    pair = args.get('currency_pair', 'EUR/USD')
    rates = {'EUR/USD': 1.0850, 'GBP/USD': 1.2720, 'USD/JPY': 154.30}
    return {'pair': pair, 'spot_rate': rates.get(pair, 1.0), 'as_of': '2026-10-27T12:00:00Z'}

registry.register_tool(
    name='get_currency_spot_rate',
    description='Retrieve real-time foreign exchange spot rate for currency pair',
    parameters_schema={'currency_pair': 'string (e.g. EUR/USD)'},
    handler=get_fx_rate_handler
)

# Simulate semantic tool matching and execution
matched_tools = registry.semantic_match_tools('Need real-time foreign exchange currency rate')
execution_result = registry.dispatch_tool_call('get_currency_spot_rate', {'currency_pair': 'EUR/USD'})

summary = {
    'matched_available_tools': matched_tools,
    'execution_telemetry': execution_result
}
print(json.dumps(summary, indent=2))

import json
import re
from dataclasses import dataclass
from typing import Dict, Any, List, Tuple

@dataclass
class SchemaRule:
    param_name: str
    expected_type: type
    required: bool = True
    min_val: float = None
    max_val: float = None
    allowed_enum: List[str] = None
    regex_pattern: str = None

class EnterpriseParameterValidator:
    def __init__(self, rules: List[SchemaRule]):
        self.rules = {r.param_name: r for r in rules}

    def validate_and_coerce(self, raw_args: Dict[str, Any]) -> Tuple[bool, Dict[str, Any], List[str]]:
        coerced = {}
        errors = []

        # Check required fields
        for name, rule in self.rules.items():
            if rule.required and name not in raw_args:
                errors.append(f'MISSING_REQUIRED_PARAM: {name} is mandatory')

        for name, val in raw_args.items():
            if name not in self.rules:
                # Flag unexpected hallucinated parameters
                errors.append(f'UNEXPECTED_PARAM: {name} is not defined in tool schema')
                continue

            rule = self.rules[name]
            target_type = rule.expected_type
            coerced_val = val

            # Type coercion
            if not isinstance(val, target_type):
                try:
                    if target_type == float:
                        coerced_val = float(val)
                    elif target_type == int:
                        coerced_val = int(val)
                    elif target_type == bool and isinstance(val, str):
                        coerced_val = val.lower() in ('true', '1', 'yes')
                    elif target_type == str:
                        coerced_val = str(val)
                    else:
                        errors.append(f'TYPE_ERROR: {name} expected {target_type.__name__}, got {type(val).__name__}')
                        continue
                except (ValueError, TypeError):
                    errors.append(f'COERCION_ERROR: Cannot coerce {name} ({val}) to {target_type.__name__}')
                    continue

            # Range validation
            if rule.min_val is not None and coerced_val < rule.min_val:
                errors.append(f'RANGE_ERROR: {name} ({coerced_val}) < minimum allowed {rule.min_val}')
            if rule.max_val is not None and coerced_val > rule.max_val:
                errors.append(f'RANGE_ERROR: {name} ({coerced_val}) > maximum allowed {rule.max_val}')

            # Enum validation
            if rule.allowed_enum and coerced_val not in rule.allowed_enum:
                errors.append(f'ENUM_ERROR: {name} must be one of {rule.allowed_enum}, got {coerced_val}')

            coerced[name] = coerced_val

        is_valid = len(errors) == 0
        return is_valid, coerced if is_valid else {}, errors

# Execution: Validate enterprise treasury transfer parameters
rules = [
    SchemaRule('account_id', str, required=True),
    SchemaRule('amount_usd', float, required=True, min_val=0.01, max_val=1000000.0),
    SchemaRule('transfer_speed', str, required=True, allowed_enum=['STANDARD', 'SAME_DAY', 'IMMEDIATE_RTGS'])
]
validator = EnterpriseParameterValidator(rules)

# Case 1: Valid call with string amount that needs coercion
valid_raw = {'account_id': 'ACC-9941', 'amount_usd': '75000.50', 'transfer_speed': 'IMMEDIATE_RTGS'}
ok1, coerced1, errs1 = validator.validate_and_coerce(valid_raw)

# Case 2: Out of bounds amount and hallucinated parameter
invalid_raw = {'account_id': 'ACC-9941', 'amount_usd': -500.0, 'transfer_speed': 'LIGHTSPEED', 'hallucinated_flag': True}
ok2, coerced2, errs2 = validator.validate_and_coerce(invalid_raw)

summary = {
    'coerced_valid_execution': {'valid': ok1, 'payload': coerced1},
    'intercepted_invalid_execution': {'valid': ok2, 'errors': errs2}
}
print(json.dumps(summary, indent=2))

