import json
import os
import re
from dataclasses import dataclass
from typing import Dict, Any, List

@dataclass
class SandboxSecurityPolicy:
    allowed_base_dir: str
    max_execution_time_seconds: float = 2.0
    forbidden_shell_characters: List[str] = None
    allow_network_egress: bool = False

class EnterpriseSecureSandbox:
    def __init__(self, policy: SandboxSecurityPolicy):
        self.policy = policy
        self.policy.forbidden_shell_characters = self.policy.forbidden_shell_characters or [';', '|', '&', '$', '`', '>', '<']

    def sanitize_file_path(self, requested_path: str) -> str:
        # Defend against Directory Traversal (e.g. ../../etc/passwd)
        clean_path = os.path.normpath(requested_path)
        if clean_path.startswith('..') or os.path.isabs(clean_path):
            raise PermissionError(f'SECURITY_VIOLATION: Directory traversal detected: {requested_path}')

        full_path = os.path.join(self.policy.allowed_base_dir, clean_path)
        # Canonical path check
        if not os.path.abspath(full_path).startswith(os.path.abspath(self.policy.allowed_base_dir)):
            raise PermissionError('SECURITY_VIOLATION: Path escapes authorized sandbox boundary')

        return full_path

    def sanitize_command_arguments(self, args: List[str]) -> List[str]:
        # Defend against Command Injection
        sanitized = []
        for arg in args:
            for char in self.policy.forbidden_shell_characters:
                if char in arg:
                    raise ValueError(f'SECURITY_VIOLATION: Forbidden shell character detected: {char} in {arg}')
            sanitized.append(arg)
        return sanitized

    def execute_sandboxed_file_read(self, relative_path: str) -> Dict[str, Any]:
        try:
            safe_path = self.sanitize_file_path(relative_path)
            return {
                'status': 'AUTHORIZED',
                'safe_resolved_path': safe_path,
                'sandbox_boundary_intact': True
            }
        except PermissionError as pe:
            return {
                'status': 'SECURITY_BLOCKED',
                'violation_type': 'DIRECTORY_TRAVERSAL_ATTACK',
                'details': str(pe)
            }

# Execution: Test security defenses against normal vs adversarial inputs
policy = SandboxSecurityPolicy(allowed_base_dir='/var/app/enterprise_workspace')
sandbox = EnterpriseSecureSandbox(policy)

# Case 1: Legitimate file read within workspace
legit_call = sandbox.execute_sandboxed_file_read('reports/q3_earnings.csv')

# Case 2: Adversarial directory traversal attempt
adversarial_call = sandbox.execute_sandboxed_file_read('../../../etc/shadow')

# Case 3: Command injection detection
injection_detected = False
try:
    sandbox.sanitize_command_arguments(['backup.sh', '; rm -rf /'])
except ValueError:
    injection_detected = True

summary = {
    'legitimate_request': legit_call,
    'adversarial_traversal_blocked': adversarial_call,
    'command_injection_neutralized': injection_detected
}
print(json.dumps(summary, indent=2))

