import json
from collections import defaultdict
from dataclasses import dataclass
from typing import Dict, List, Tuple

@dataclass
class AgentBallot:
    agent_id: str
    ranked_preferences: List[str]  # First to last
    confidence_score: float        # 0.0 to 1.0
    quadratic_credits_spent: Dict[str, int] # Option -> Votes

class EnterpriseVotingEngine:
    @staticmethod
    def tally_simple_majority(ballots: List[AgentBallot]) -> Dict[str, int]:
        # Counts only first-choice votes
        tally = defaultdict(int)
        for b in ballots:
            if b.ranked_preferences:
                tally[b.ranked_preferences[0]] += 1
        return dict(tally)

    @staticmethod
    def tally_borda_count(ballots: List[AgentBallot], all_options: List[str]) -> Dict[str, int]:
        m = len(all_options)
        scores = {opt: 0 for opt in all_options}
        for b in ballots:
            for rank_idx, opt in enumerate(b.ranked_preferences):
                pts = (m - 1) - rank_idx
                scores[opt] += max(0, pts)
        return scores

    @staticmethod
    def tally_confidence_weighted(ballots: List[AgentBallot]) -> Dict[str, float]:
        # Weights first choice by agent confidence
        weighted = defaultdict(float)
        for b in ballots:
            first_choice = b.ranked_preferences[0]
            weighted[first_choice] += b.confidence_score
        return {k: round(v, 2) for k, v in weighted.items()}

    @staticmethod
    def tally_quadratic_voting(ballots: List[AgentBallot]) -> Dict[str, int]:
        total_votes = defaultdict(int)
        for b in ballots:
            for opt, v in b.quadratic_credits_spent.items():
                total_votes[opt] += v
        return dict(total_votes)

# Execution: 4 specialized agents voting on Cloud Region Expansion: 'EU_WEST', 'US_EAST', 'APAC_SOUTH'
options = ['EU_WEST', 'US_EAST', 'APAC_SOUTH']
ballots = [
